installer-gui-script.script:

function checkPhotoshopVersions() {
    var versions = {
        "2026": system.files.fileExistsAtPath("/Applications/Adobe Photoshop 2026"),
        "2025": system.files.fileExistsAtPath("/Applications/Adobe Photoshop 2025"),
        "2024": system.files.fileExistsAtPath("/Applications/Adobe Photoshop 2024"),
        "2023": system.files.fileExistsAtPath("/Applications/Adobe Photoshop 2023"),
        "2022": system.files.fileExistsAtPath("/Applications/Adobe Photoshop 2022"),
        "2021": system.files.fileExistsAtPath("/Applications/Adobe Photoshop CC 2021"),
        "2020": system.files.fileExistsAtPath("/Applications/Adobe Photoshop CC 2020"),
        "2019": system.files.fileExistsAtPath("/Applications/Adobe Photoshop CC 2019")
    };
    return versions;
}

function isPSVersion(version) {
    return checkPhotoshopVersions()[version] === true;
}

function countInstalledPS() {
    var versions = checkPhotoshopVersions();
    var count = 0;
    for (var key in versions) {
        if (versions[key]) count++;
    }
    return count;
}

// 设置选择状态到环境变量
function updateChoices() {
    var versions = ["2026", "2025", "2024", "2023", "2022", "2021", "2020", "2019"];
    var selected = [];

    for (var i = 0; i < versions.length; i++) {
        if (choices["ps" + versions[i]].selected) {
            selected.push(versions[i]);
        }
    }

    // 将选择的版本保存到文件，供 postinstall 读取
    system.run("/bin/echo", selected.join(","), ">", "/tmp/superstaroff_ps_versions.txt");
}


function checkInstallation() {
    // 检查 macOS 版本（至少需要 10.15）
    if (system.compareVersions(system.version.ProductVersion, '10.15') < 0) {
        my.result.title = '系统版本过低';
        my.result.message = 'SuperStarOff 需要 macOS 10.15 (Catalina) 或更高版本。';
        my.result.type = 'Fatal';
        return false;
    }

    // 检查是否安装了 Photoshop
    var psCount = countInstalledPS();
    if (psCount === 0) {
        my.result.title = '未检测到 Photoshop';
        my.result.message = '系统中未检测到任何版本的 Adobe Photoshop。\n\n您可以继续安装 SuperStarOff，但需要在安装 Photoshop 后手动配置。';
        my.result.type = 'Warning';
    }

    return true;
}
